class File:
    def __init__(self):
        self.entree = []
        self.sortie = []
    def enfiler(self, x):
        self.entree.append(x)
    def defiler(self):
        if self.sortie == []:
            while self.entree != []:
                self.sortie.append(self.entree.pop())
        return self.sortie.pop()

f = File()
for x in [1, 2, 3]:
    f.enfiler(x)
assert f.defiler() == 1 and f.defiler() == 2
